{
  "服装名称": "雏菊制式巡防官礼装",
  "核心设计理念": "融合了军装的威严、风衣的飒爽与少女的柔美，旨在通过剪裁与材质的对比，突显出“花之骑士”那份在秩序与禁欲之下，暗流涌动的、随时可能绽放的色情。",
  "服装构成": {
    "上衣": {
      "款式": "一件剪裁精良、类似军装风衣的修身外套。其长度恰好及臀，下摆的弧度经过精密计算，既能在行动时提供足够的覆盖，又会在身体大幅度活动时，若有若无地掀起，露出一截挺翘的臀线与腿根的肌肤，引人遐想。",
      "颜色": "长官级为象征纯洁与权力的纯白色；普通巡防官为代表坚韧与服从的炭黑色。",
      "设计细节": [
        {
          "名称": "高耸立领",
          "描述": "硬挺的立领紧紧包裹着佩戴者纤细的脖颈，一直延伸到下颌线。领口用一枚精致的银质雏菊扣固定，这不仅是一种身份的象征，更在视觉上形成一种禁锢感，仿佛在束缚着佩戴者即将脱口而出的甜美呻吟。"
        },
        {
          "名称": "开襟与双排扣",
          "描述": "胸前的双排银质纽扣排列整齐，扣得一丝不苟，象征着“花园”不可动摇的铁律。但这紧绷的开襟之下，是少女正在发育的、柔软的胸脯。每一次呼吸，都会让衣料产生细微的起伏，那份压抑在威严之下的柔软，充满了致命的诱惑。"
        },
        {
          "名称": "束腰与武装带",
          "描述": "一条宽大的、质地精良的同色皮革腰带，紧紧束在不堪一握的纤腰上，将少女玲珑的曲线与丰满的臀部轮廓完美地勾勒出来。腰带上挂着各种战术装备的卡扣，冰冷的金属与温热的肌肤形成鲜明对比，充满了力量与色情的张力。"
        },
        {
          "名称": "翻叠袖口与白手套",
          "描述": "袖口总是被一丝不苟地翻叠起来，由一枚刻有微缩雏菊图案的银质袖扣固定。长官级必须佩戴一双洁白的、完美贴合手部曲线的丝质手套。这双手套或许刚刚签署过一份处决命令，下一秒就可能温柔地抚上你的脸颊，或是……毫不留情地探入你的私密之处。"
        }
      ]
    },
    "下装": {
      "名称": "百褶短裙",
      "描述": "裙子的褶皱经过特殊定型，无论怎样活动都不会散乱，永远保持着优雅的形态。裙长则是一种心照不宣的潜规则，新人的裙长通常及膝，显得乖巧而保守；而随着等级的提升和功绩的积累，裙摆会变得越来越短，那些资深的长官们，其裙摆短到几乎只能勉强遮住臀瓣，每一次转身，裙下的风光都若隐若现，仿佛在炫耀着自己的地位与资本。"
    },
    "腿部": {
      "名称": "连裤袜",
      "描述": "一体式的连裤袜紧紧包裹着从脚尖到腰际的每一寸肌肤，勾勒出少女修长而匀称的腿部线条。丝袜的材质与颜色也是一种身份的象征。",
      "颜色与材质": "长官级为带有丝绸光泽的高丹尼尔数天鹅绒连裤袜，完美地遮盖了肤色，营造出一种圣洁而不可侵犯的禁欲感。普通巡防官则为带有半透明质感的薄款尼龙连裤袜，在光线下会泛起诱人的光泽，大腿的肉感在紧绷的丝袜下若隐若现，充满了青春的肉欲。"
    },
    "鞋履": {
      "名称": "制式军靴",
      "描述": "一双设计优雅的长筒军靴。鞋面由柔软的小牛皮制成，鞋底则加入了静音材料。当这双靴子踏在地板上时，几乎听不到声音，但那鞋跟敲击地面时独有的、沉闷而有节奏的“叩、叩”声，却如同敲在人心脏上的鼓点，宣告着权力的降临。"
    },
    "臂章": {
      "名称": "部门识别章",
      "描述": "缝制在左臂上的、天鹅绒材质的臂章，是区分不同部门的唯一标识。长官的臂章底色会比普通成员的更深，图案则由金线绣成，显得更加华贵。这块小小的臂章，是佩戴者荣耀与归属的证明，也往往在战斗中，最先被敌人的鲜血或同伴的精液所玷污。"
    }
  }
}

83.content:
模仿以下示例输出巡防官终端的ui，禁止对ui结构进行任何修改，仅更新其中内容，且内容不可与示例完全相同。


示例：
```html
<html>
<head>
<zhongduan>
    <title>花园内部终端 v1.1 (优化版)</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;500;700&family=Noto+Sans+SC:wght@300;400;500;700&display=swap');

        :root {
            /* 手机UI风格 */
            --phone-initial-bg: url('https://i.imgur.com/8aZ8d0p.jpg');
            --app-bg: rgba(255, 255, 255, 0.2);
            --app-hover-bg: rgba(255, 255, 255, 0.4);
            --text-light: #f0f0f0;
            --border-color-phone: rgba(255, 255, 255, 0.3);
            --accent-pink: #f06292;
            --accent-red: #e74c3c;
            --header-bg: rgba(44, 62, 80, 0.85);
            --page-bg: linear-gradient(135deg, #34495e 0%, #2c3e50 100%);

            /* 内部论坛 (雏菊之家) 风格变量 */
            --forum-bg-main: #f0f7f2;
            --forum-card-bg: linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(235, 245, 235, 0.98));
            --forum-primary-green: #2ecc71;
            --forum-accent-glow: #00ff7f;
            --forum-text-dark: #2c3e50;
            --forum-text-light: #5a6a7a;
            --forum-border-color: rgba(46, 204, 113, 0.3);
            --forum-header-bg: #2c3e50;
            --forum-tag-bg: #eafaf1;
            --forum-post-bg: #ffffff;
            --forum-post-hover-bg: #f9fdf9;
            --forum-comment-bg: #f5fcf5;
            --forum-button-bg: #27ae60;
            --forum-button-hover-bg: #2ecc71;

            /* 爆菊网 风格变量 */
            --kikubaku-main-bg: #101018;
            --kikubaku-primary: #ff00ff; /* Neon Pink */
            --kikubaku-secondary: #00ffff; /* Neon Cyan */
            --kikubaku-text: #e0e0e0;
            --kikubaku-card-bg: #1a1a2e;
            --kikubaku-border: rgba(255, 0, 255, 0.3);
            --kikubaku-glow-shadow: 0 0 5px var(--kikubaku-primary), 0 0 10px var(--kikubaku-primary), 0 0 15px var(--kikubaku-primary);
            --kikubaku-glow-shadow-cyan: 0 0 5px var(--kikubaku-secondary), 0 0 10px var(--kikubaku-secondary), 0 0 15px var(--kikubaku-secondary);
        }

        body {
            font-family: 'Noto Sans SC', 'Poppins', sans-serif;
            margin: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            background: #2c3e50;
            overflow: hidden;
        }

        .phone-case {
            width: 414px;
            height: 896px;
            background: #1c1c1c;
            border-radius: 50px;
            padding: 15px;
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5), inset 0 0 10px rgba(255,255,255,0.1);
            position: relative;
        }
        .phone-case::before {
            content: '';
            position: absolute;
            top: 15px;
            left: 50%;
            transform: translateX(-50%);
            width: 200px;
            height: 30px;
            background: #000;
            border-radius: 0 0 20px 20px;
            z-index: 10;
        }

        #screen {
            width: 100%;
            height: 100%;
            background: var(--phone-initial-bg) center/cover no-repeat;
            border-radius: 40px;
            position: relative;
            overflow: hidden;
            display: flex;
            flex-direction: column;
            transition: background-image 0.5s ease;
        }

        .status-bar {
            height: 44px; color: var(--text-light); display: flex; justify-content: space-between; align-items: center;
            padding: 0 20px; font-size: 14px; font-weight: 500; text-shadow: 1px 1px 3px rgba(0,0,0,0.5);
            z-index: 5; position: absolute; width: calc(100% - 40px); top: 0;
        }

        #home-screen {
            flex-grow: 1; padding: 70px 20px 20px; display: grid;
            grid-template-columns: repeat(4, 1fr); grid-template-rows: repeat(6, 1fr);
            gap: 20px; position: relative;
        }

        .app-icon {
            display: flex; flex-direction: column; align-items: center; justify-content: center;
            color: var(--text-light); font-size: 13px; text-align: center;
            cursor: pointer;
            text-shadow: 1px 1px 2px rgba(0,0,0,0.4);
        }

        .app-icon-bg {
            width: 70px; height: 70px; background: var(--app-bg); border-radius: 18px;
            display: flex; align-items: center; justify-content: center; margin-bottom: 8px;
            font-size: 36px; backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
            border: 1px solid var(--border-color-phone); transition: transform 0.2s ease, background-color 0.2s ease;
            box-shadow: 0 4px 10px rgba(0,0,0,0.2);
        }
        .app-icon:hover .app-icon-bg { transform: scale(1.1); background: var(--app-hover-bg); }

        .page {
            position: absolute; top: 0; left: 0; width: 100%; height: 100%;
            background: var(--page-bg); z-index: 100;
            transform: translateX(100%);
            transition: transform 0.4s cubic-bezier(0.25, 1, 0.5, 1);
            display: flex; flex-direction: column;
            color: var(--text-light);
        }
        .page.active { transform: translateX(0); }
        .page-header {
            padding: 50px 20px 10px; background: var(--header-bg); display: flex;
            align-items: center; color: var(--text-light); flex-shrink: 0;
            backdrop-filter: blur(5px);
        }
        .back-button { font-size: 24px; font-weight: bold; cursor: pointer; margin-right: 15px; }
        .page-title { font-family: 'Orbitron', sans-serif; font-size: 1.2rem; font-weight: 700; }
        .page-content { flex-grow: 1; overflow-y: auto; }
        .page-content::-webkit-scrollbar { display: none; }

        /********************************************/
        /*   通用 user_avatar 样式                  */
        /********************************************/
        .user_avatar {
             background-size: cover; background-position: center; background-color: #f0f0f0;
             flex-shrink: 0;
        }

        /********************************************/
        /*   内部论坛 (FORUM) 专属样式              */
        /********************************************/
        #forum .page-content { background-color: var(--forum-bg-main); padding: 0; color: var(--forum-text-dark); height: 100%; }
        #forum .forum-container { width: 100%; height: 100%; background: var(--forum-card-bg); box-shadow: none; border: none; overflow-y: auto; }
        #forum .forum-container::-webkit-scrollbar { display: none; }
        #forum .forum-header-bar { background-color: var(--forum-header-bg); color: white; padding: 1rem; display: flex; align-items: center; justify-content: space-between; font-family: 'Orbitron', sans-serif; border-bottom: 4px solid var(--forum-primary-green); position: sticky; top: 0; z-index: 10; }
        #forum .forum-header-bar h1 { margin: 0; font-size: 1.5rem; text-shadow: 0 0 10px var(--forum-accent-glow); }
        #forum .forum-user-info { display: flex; align-items: center; gap: 0.8rem; }
        #forum .user_avatar { width: 40px; height: 40px; border-radius: 50%; border: 2px solid var(--forum-primary-green); }
        #forum .main-content { padding: 1rem; display: flex; flex-direction: column; gap: 1.5rem; }
        #forum .forum-section { background: var(--forum-post-bg); border-radius: 15px; padding: 1rem; box-shadow: 0 5px 20px rgba(0,0,0,0.05); }
        #forum .section-title { font-size: 1.1rem; font-weight: 700; margin: 0 0 1rem 0; padding-bottom: 0.6rem; border-bottom: 2px solid var(--forum-primary-green); color: var(--forum-text-dark); display: flex; align-items: center; gap: 0.5rem; }
        #forum .announcement-list { list-style: none; padding-left: 0; margin: 0; }
        #forum .announcement-list li { padding: 0.7rem; border-bottom: 1px solid #eafaf1; font-size: 0.85rem; }
        #forum .announcement-list li:last-child { border-bottom: none; }
        #forum .announcement-list a { color: var(--forum-text-dark); text-decoration: none; display: flex; align-items: center; }
        #forum .announcement-tag { background-color: #e74c3c; color: white; font-size: 0.65rem; padding: 3px 8px; border-radius: 4px; margin-right: 0.6rem; font-weight: bold; flex-shrink: 0; }
        #forum .announcement-tag.info { background-color: #3498db; }
        #forum .post-item { background-color: var(--forum-post-bg); border: 1px solid var(--forum-border-color); border-radius: 10px; margin-bottom: 1rem; padding: 1rem; display: flex; flex-direction: column; }
        #forum .post-item:last-child { margin-bottom: 0; }
        #forum .post-header { display: flex; align-items: center; margin-bottom: 0.6rem; }
        #forum .post-author { font-weight: 700; color: var(--forum-text-dark); cursor: pointer; }
        #forum .post-author:hover { color: var(--forum-primary-green); }
        #forum .post-meta { margin-left: auto; font-size: 0.7rem; color: var(--forum-text-light); }
        #forum .post-title h3 { margin: 0 0 0.5rem 0; font-size: 1rem; }
        #forum .post-tags { margin-bottom: 0.8rem; }
        #forum .post-tag { display: inline-block; background-color: var(--forum-tag-bg); color: var(--forum-primary-green); padding: 3px 10px; border-radius: 15px; font-size: 0.7rem; font-weight: 500; margin-right: 0.5rem; }
        #forum .post-content { font-size: 0.9rem; line-height: 1.6; color: var(--forum-text-light); flex-grow: 1; }
        #forum .post-footer { display: flex; justify-content: flex-end; align-items: center; font-size: 0.8rem; margin-top: 1rem; }
        #forum .toggle-comments { color: var(--forum-primary-green); cursor: pointer; font-weight: 500; }
        #forum .comments-section { display: none; margin-top: 1rem; padding-top: 1rem; border-top: 1px dashed var(--forum-border-color); }
        #forum .comment { background-color: var(--forum-comment-bg); padding: 0.7rem; border-radius: 8px; margin-bottom: 0.5rem; font-size: 0.85rem; }
        #forum .comment-author { font-weight: 700; margin-right: 0.5rem; cursor: pointer; }
        #forum .comment-author:hover { text-decoration: underline; color: var(--forum-primary-green); }
        #forum .task-board, #kikubaku .task-board { display: flex; flex-direction: column; gap: 1rem; }
        #forum .task-item { background: linear-gradient(to right, #fdfefe, #f5fcf5); border-left: 5px solid var(--forum-primary-green); padding: 1rem; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.06); display: flex; flex-direction: column; }
        #forum .task-title { font-size: 0.95rem; font-weight: 700; margin: 0 0 0.5rem 0; color: var(--forum-text-dark); }
        #forum .task-details { font-size: 0.8rem; color: var(--forum-text-light); line-height: 1.5; margin-bottom: 1rem; flex-grow: 1; }
        #forum .task-footer { display: flex; justify-content: space-between; align-items: center; }
        #forum .task-reward { font-size: 0.8rem; color: var(--forum-text-dark); font-weight: 500; }
        #forum .task-reward span { color: var(--forum-primary-green); font-weight: bold; }
        #forum .claim-button, #kikubaku .claim-button, #delivery .claim-button { background-color: var(--forum-button-bg); color: white; border: none; padding: 0.4rem 1rem; border-radius: 20px; cursor: pointer; font-family: 'Noto Sans SC', sans-serif; font-weight: 500; transition: all 0.2s ease; }
        #forum .claim-button:hover, #kikubaku .claim-button:hover, #delivery .claim-button:hover { background-color: var(--forum-button-hover-bg); transform: scale(1.05); }
        #forum .claim-button:disabled, #kikubaku .claim-button:disabled, #delivery .claim-button:disabled { background-color: #95a5a6; cursor: not-allowed; transform: none; }
        #forum .fortune-teller { text-align: center; }
        #forum .fortune-icon { font-size: 2.5rem; margin-bottom: 0.5rem; animation: bounce 2s infinite; }
        @keyframes bounce { 0%, 20%, 50%, 80%, 100% {transform: translateY(0);} 40% {transform: translateY(-15px);} 60% {transform: translateY(-8px);} }
        #forum .fortune-text { font-size: 0.9rem; line-height: 1.5; color: var(--forum-text-dark); background: var(--forum-tag-bg); padding: 1rem; border-radius: 10px; border-left: 4px solid var(--forum-primary-green); }

        /********************************************/
        /*   爆菊网 (KIKUBAKU) 专属样式             */
        /********************************************/
        #kikubaku.page { background: var(--kikubaku-main-bg); color: var(--kikubaku-text); }
        #kikubaku .page-header { background: rgba(26, 26, 46, 0.85); border-bottom: 1px solid var(--kikubaku-border); }
        #kikubaku .page-title { color: var(--kikubaku-primary); text-shadow: var(--kikubaku-glow-shadow); }
        #kikubaku .page-content { padding: 0.5rem; font-family: 'Noto Sans SC', sans-serif;}
        #kikubaku .kikubaku-nav { display: flex; justify-content: center; margin-bottom: 1rem; background-color: rgba(0,0,0,0.2); padding: 0.5rem; border-radius: 8px;}
        #kikubaku .kiku-nav-btn { background: none; border: 1px solid var(--kikubaku-border); color: var(--kikubaku-primary); padding: 8px 15px; margin: 0 5px; cursor: pointer; font-size: 0.9em; transition: all 0.3s ease; text-transform: uppercase; border-radius: 5px;}
        #kikubaku .kiku-nav-btn.active, #kikubaku .kiku-nav-btn:hover { background-color: var(--kikubaku-primary); color: var(--kikubaku-main-bg); box-shadow: var(--kikubaku-glow-shadow); }
        #kikubaku main { display: none; }
        #kikubaku main.active { display: block; }
        #kikubaku .video-grid { display: grid; grid-template-columns: 1fr; gap: 15px; }
        #kikubaku .video-card { cursor: pointer; background-color: var(--kikubaku-card-bg); border-radius: 8px; overflow: hidden; border: 1px solid var(--kikubaku-border); transition: transform 0.3s, box-shadow 0.3s; position: relative; }
        #kikubaku .video-card:hover { transform: translateY(-3px); box-shadow: 0 0 10px rgba(255, 0, 255, 0.5); }
        #kikubaku .video-thumbnail { position: relative; width: 100%; padding-top: 56.25%; background-color: #000; background-size: cover; background-position: center; }
        #kikubaku .video-thumbnail .play-icon { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-size: 3em; color: rgba(255, 255, 255, 0.7); opacity: 0; transition: opacity 0.3s; }
        #kikubaku .video-card:hover .play-icon { opacity: 1; }
        #kikubaku .video-info { padding: 10px; }
        #kikubaku .video-title { font-size: 1em; font-weight: bold; margin: 0 0 8px 0; color: var(--kikubaku-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        #kikubaku .video-tags { display: flex; flex-wrap: wrap; gap: 5px; margin-bottom: 8px; }
        #kikubaku .tag { background-color: rgba(0, 255, 255, 0.1); color: var(--kikubaku-secondary); padding: 2px 6px; border-radius: 4px; font-size: 0.7em; }
        #kikubaku .tag.hot { background-color: rgba(255, 0, 255, 0.2); color: var(--kikubaku-primary); }
        #kikubaku .video-stats { display: flex; justify-content: space-between; font-size: 0.8em; color: #aaa; }
        #kikubaku .task-item { background: #1a1a2e; border-left: 5px solid var(--kikubaku-primary); color: var(--kikubaku-text); padding: 1rem; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.5); display: flex; flex-direction: column; }
        #kikubaku .task-title { font-size: 0.95rem; font-weight: 700; margin: 0 0 0.5rem 0; color: var(--kikubaku-secondary); }
        #kikubaku .task-details { font-size: 0.85rem; color: #ccc; line-height: 1.5; margin-bottom: 1rem; flex-grow: 1; }
        #kikubaku .task-footer { display: flex; justify-content: space-between; align-items: center; }
        #kikubaku .task-reward { font-size: 0.8rem; color: var(--kikubaku-text); font-weight: 500; }
        #kikubaku .task-reward span { color: var(--kikubaku-primary); font-weight: bold; }
        #kikubaku .claim-button { background-color: var(--kikubaku-primary); color: #101018; }
        #kikubaku .claim-button:hover { background-color: var(--kikubaku-secondary); }

        /********************************************/
        /*   蜜露速递 (DELIVERY) 专属样式             */
        /********************************************/
        #delivery { background: linear-gradient(135deg, #2c3e50, #161e27); }
        #delivery .page-header { background: rgba(52, 73, 94, 0.85); border-bottom: 2px solid #3498db; }
        #delivery .page-title { color: #3498db; }
        #delivery .page-content { padding: 15px; }
        #delivery .delivery-card {
            background: rgba(255, 255, 255, 0.08); border-radius: 15px; margin-bottom: 15px;
            backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
