            const DB_NAME = 'GardenPhoneDB';
            const DB_VERSION = 1;
            const STORE_NAME = 'wallpapers';
            const WALLPAPER_KEY = 'currentWallpaper';
            let db;

            function initDB() {
                return new Promise((resolve, reject) => {
                    const request = indexedDB.open(DB_NAME, DB_VERSION);
                    request.onerror = event => reject('数据库打开报错', event);
                    request.onsuccess = event => {
                        db = event.target.result;
                        console.log('数据库打开成功');
                        resolve(db);
                    };
                    request.onupgradeneeded = event => {
                        db = event.target.result;
                        if (!db.objectStoreNames.contains(STORE_NAME)) {
                            db.createObjectStore(STORE_NAME);
                            console.log('对象仓库创建成功');
                        }
                    };
                });
            }

            function saveWallpaperToDB(blob) {
                return new Promise((resolve, reject) => {
                    if (!db) { reject('数据库未初始化'); return; }
                    const transaction = db.transaction([STORE_NAME], 'readwrite');
                    const store = transaction.objectStore(STORE_NAME);
                    const request = store.put(blob, WALLPAPER_KEY);
                    request.onsuccess = () => resolve();
                    request.onerror = (event) => reject('写入失败', event);
                });
            }

            function loadWallpaperFromDB() {
                return new Promise((resolve, reject) => {
                     if (!db) { reject('数据库未初始化'); return; }
                    const transaction = db.transaction([STORE_NAME], 'readonly');
                    const store = transaction.objectStore(STORE_NAME);
                    const request = store.get(WALLPAPER_KEY);
                    request.onsuccess = (event) => {
                        const blob = event.target.result;
                        if (blob) {
                            if (currentWallpaperUrl) URL.revokeObjectURL(currentWallpaperUrl);
                            currentWallpaperUrl = URL.createObjectURL(blob);
                            screen.style.backgroundImage = `url(${currentWallpaperUrl})`;
                        }
                        resolve();
                    };
                    request.onerror = (event) => reject('读取失败', event);
                });
            }
            // #endregion

            // #region --- SillyTavern 指令交互 ---
            window.triggerSlash = (command) => {
                const isSimpleText = !command.trim().startsWith('/');
                const finalCommand = isSimpleText ? `/send *${command}*` : command;
                console.log(`执行ST命令: ${finalCommand}`);
                if (typeof triggerSlashWithResult === 'function') {
                    triggerSlashWithResult(finalCommand).then(result => console.log('指令结果:', result));
                } else if (window.parent && window.parent.postMessage) {
                    window.parent.postMessage({ type: "executeSlashCommand", command: finalCommand }, "*");
                }
            };
            // #endregion

            // #region --- 手机核心功能 (壁纸, 导航, 时钟) ---
            wallpaperApp.addEventListener('click', () => {
                const input = document.createElement('input');
                input.type = 'file';
                input.accept = 'image/*';
                input.onchange = async e => {
                    const file = e.target.files[0];
                    if (!file || !file.type.startsWith('image/')) return;
                    try {
                        await saveWallpaperToDB(file);
                        await loadWallpaperFromDB();
                    } catch (error) {
                        alert('保存壁纸失败！');
                        console.error('IndexedDB 错误:', error);
                    }
                };
                input.click();
            });

            window.openPage = (pageId) => {
                closeAllPages();
                const page = document.getElementById(pageId);
                if(page) page.classList.add('active');
            };

            window.closeAllPages = () => document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));

            const updateTime = () => {
                const timeEl = document.getElementById("time");
                if (!timeEl) return;
                const now = new Date();
                timeEl.textContent = `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`;
            };
            // #endregion

            // #region --- 通用任务与交互函数 ---
            window.claimTask = (button, source) => {
                const taskItem = button.closest('.task-item');
                const title = taskItem.querySelector('.task-title').dataset.title;
                const choiceText = `[任务已领取: ${source}] ${title}`;
                triggerSlash(`/send ${choiceText}|/trigger`);
                button.textContent = '已接取';
                button.disabled = true;
            };
            // #endregion

            // #region --- 内部论坛 (雏菊之家) 专属JS ---
            window.toggleComments = (element) => {
                const commentsSection = element.closest('.post-item').querySelector('.comments-section');
                const isVisible = commentsSection.style.display === 'block';
                commentsSection.style.display = isVisible ? 'none' : 'block';
                element.textContent = isVisible ? element.textContent.replace('收起评论', '查看评论') : element.textContent.replace('查看评论', '收起评论');
            };

            window.replyTo = (postTitle, authorName) => {
                triggerSlash(`/send 回复 @${authorName} 关于“${postTitle}”：`);
            };
            // #endregion

            // #region --- 爆菊网 专属JS ---
            const kikuNavButtons = document.querySelectorAll('#kikubaku .kiku-nav-btn');
            const kikuMainSections = document.querySelectorAll('#kikubaku main');
            const kikuVideoGrid = document.querySelector('#kikubaku .video-grid');
            const kikuMissionBoard = document.querySelector('#kikubaku .task-board');

            // 果农注：将模拟数据定义为常量，结构更清晰。
            const MOCK_VIDEOS = [
                { title: '新人巡防官初次实战(含哭腔)', tags: ['#新人', '#口交净化', '#D级', '#hot'], views: '1.2M', date: '一个月前', thumbnail: 'https://i.imgur.com/u7n9xpb.jpg' },
                { title: '黑蔷薇的训宠教学', tags: ['#长官', '#肉便器', '#强暴', '#调教'], views: '90K', date: '1天前', thumbnail: 'https://i.imgur.com/A6jM2Th.jpg' },
                { title: '公共厕所突击检查！制服少女的漏尿瞬间', tags: ['#公共露出', '#失禁', '#制服', '#hot'], views: '2.1M', date: '半年前', thumbnail: 'https://i.imgur.com/sC4xT0b.jpg' },
                { title: '哺乳期巡防官的榨奶服务？特殊任务流出', tags: ['#泌乳', '#特殊任务', '#圣痕'], views: '38K', date: '12小时前', thumbnail: 'https://i.imgur.com/8Q7pZcR.jpg' },
            ];
             const MOCK_MISSIONS = [
                { title: '[悬赏]偷拍星宫琉璃洗澡', details: '目标：星宫琉璃。需求：无修正沐浴视频，时长不少于3分钟。风险极高，匿名发布。', reward: '5000 加密积分（可换成等价其他货币）' },
                { title: '[委托]C级净化任务代跑', details: '地点：新宿二丁目。本人临时有约，寻一位雏菊姐妹代为执行常规净化任务。任务轻松，报酬可议。', reward: '任务积分 + 250 加密积分' },
                { title: '[情报]收集巡防长官“龙依”的超能力情报', details: '可能会有交战，需要提前知晓其超能力的相关情报，弱点以及发动频率', reward: '1500 加密积分' },
            ];

            kikuNavButtons.forEach(button => {
                button.addEventListener('click', () => {
                    kikuNavButtons.forEach(btn => btn.classList.remove('active'));
                    button.classList.add('active');
                    const targetId = button.getAttribute('data-target');
                    kikuMainSections.forEach(section => {
                        section.classList.remove('active');
                        if (section.id === targetId) section.classList.add('active');
                    });
                });
            });

            function populateKikuVideos() {
                if(!kikuVideoGrid) return;
                kikuVideoGrid.innerHTML = '';
                MOCK_VIDEOS.forEach(video => {
                    const card = document.createElement('div');
                    card.className = 'video-card';
                    card.onclick = () => triggerSlash(`观看 #${video.title}#`);
                    card.innerHTML = `
                        <div class="video-thumbnail" style="background-image: url('${video.thumbnail}');">
                            <div class="play-icon">▶</div>
                        </div>
                        <div class="video-info">
                            <h3 class="video-title">${video.title}</h3>
                            <div class="video-tags">
                                ${video.tags.map(tag => `<span class="tag ${tag.includes('hot') ? 'hot' : ''}">${tag}</span>`).join('')}
                            </div>
                            <div class="video-stats">
                                <span>${video.views} 观看</span>
                                <span>${video.date}</span>
                            </div>
                        </div>`;
                    kikuVideoGrid.appendChild(card);
                });
            }

            function populateKikuMissions() {
                if(!kikuMissionBoard) return;
                kikuMissionBoard.innerHTML = '';
                MOCK_MISSIONS.forEach(mission => {
                    const card = document.createElement('div');
                    card.className = 'task-item';
                    card.innerHTML = `
                        <h4 class="task-title" data-title="${mission.title}">${mission.title}</h4>
                        <p class="task-details">${mission.details}</p>
                        <div class="task-footer">
                            <div class="task-reward">报酬: <span>${mission.reward}</span></div>
                            <button class="claim-button" onclick="claimTask(this, 'KikuBaku')">接取</button>
                        </div>`;
                    kikuMissionBoard.appendChild(card);
                });
            }
            // #endregion

            // #region --- 初始化函数调用 ---
            async function initialize() {
                try {
                    await initDB();
                    await loadWallpaperFromDB();
                } catch (error) {
                    console.error("初始化失败:", error);
                }
                updateTime();
                setInterval(updateTime, 60000);
                populateKikuVideos();
                populateKikuMissions();
            }

            initialize();
            // #endregion
        });
    </script>
</zhongduan>
</body>
</html>
